  gl:  mkV({c:'#56707f', ds:true, glow:'#ffd9a4', gk:0.85, m:0, lk:0.05}),           // gate-lounge glazing: lit lounges at night
  cw:  mkV({c:'#6d8a99', ds:true, glow:'#ffe6c2', gk:0.75, m:0, lk:0.05}),          // hall curtain walls
  sk:  mkV({c:'#9db3bd', ds:true, glow:'#ffe2b8', gk:0.35, m:0, lk:0}),             // skylights / clerestories (lit from inside)
