    let dt = p1[0] - p0[0], dr = p1[1] - p0[1]; const l = Math.hypot(dt, dr) || 1; dt /= l; dr /= l;
    const nt = -dr, nr = dt, ring = [], nring = [], jg = o.jag ? o.jag[i] || 0 : 0;
